const esc=(value)=>String(value??"").replace(/[&<>"']/g,(c)=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[c]));
const clone=(x)=>JSON.parse(JSON.stringify(x));
const txt=(x,unit="")=>x===null||x===undefined||x===""||!Number.isFinite(Number(x))?"—":new Intl.NumberFormat("zh-CN",{maximumFractionDigits:3}).format(Number(x))+unit;
const fmtTime=(x)=>{if(!x)return "—";let d=typeof x==="number"?new Date(x>1e12?x:x*1000):new Date(x);return Number.isNaN(d.getTime())?String(x):d.toLocaleString("zh-CN",{hour12:false});};
const duration=(x)=>{if(x===null||x===undefined||!Number.isFinite(Number(x)))return "—";let n=Math.max(0,Math.round(Number(x)));return `${Math.floor(n/3600)}时${Math.floor(n%3600/60)}分${n%60}秒`;};
const id=()=>"ui-"+(crypto.randomUUID?.()||Math.random().toString(36).slice(2));
function notify(message,bad=false){const el=$("toast");el.textContent=message;el.classList.toggle("bad",bad);el.hidden=false;clearTimeout(notify.timer);notify.timer=setTimeout(()=>el.hidden=true,6000);}
async function api(path,method="GET",body){const options={method,headers:{Accept:"application/json"}};if(body!==undefined){options.headers["Content-Type"]="application/json";options.body=JSON.stringify(body);}let response;try{response=await fetch(path,options);}catch(error){throw new Error("无法连接本地服务："+error.message);}let data;try{data=await response.json();}catch{throw new Error(`服务返回非 JSON 数据（HTTP ${response.status}）`);}if(!response.ok)throw new Error(data.error||`请求失败（HTTP ${response.status}）`);return data;}
function setPage(page){state.page=page;for(const el of document.querySelectorAll(".page")){const active=el.id==="page-"+page;el.hidden=!active;el.classList.toggle("active",active);}for(const button of document.querySelectorAll("[data-page]"))button.setAttribute("aria-current",button.dataset.page===page?"page":"false");try{history.replaceState(null,"",`#${page}`);}catch{}if(page==="monitor")refreshMonitor();if(page==="test")refreshResources();if(page==="compare")refreshRuns();}
function options(select,items,label,value,placeholder="请选择"){const previous=select.value;select.replaceChildren();select.add(new Option(placeholder,""));for(const item of items)select.add(new Option(label(item),String(value(item))));if([...select.options].some((x)=>x.value===previous))select.value=previous;}
function cat(name){const x=state.catalog[name];return Array.isArray(x)?x:Object.values(x||{});}
function lookup(collection,key){return cat(collection).find((item)=>String(item.id??item.kind??item.name)===String(key));}
function itemLabel(collection,key){const found=lookup(collection,key);return found?.label||found?.name||labels[key]||key;}
function setPath(object,path,value){const parts=path.split(".");let target=object;for(let i=0;i<parts.length-1;i++)target=target[parts[i]];target[parts.at(-1)]=value;}
function getPath(object,path){return path.split(".").reduce((x,k)=>x?.[k],object);}
function field(path,value,allowed){const name=path.split(".").at(-1);const label=fieldNames[name]||name;let input;if(allowed){input=`<select data-path="${esc(path)}">${allowed.map((a)=>`<option value="${esc(a)}" ${String(a)===String(value)?"selected":""}>${esc(labels[a]||a)}</option>`).join("")}</select>`;}else if(Array.isArray(value)){input=`<input data-path="${esc(path)}" data-array="true" type="text" value="${esc(value.join(", "))}">`;}else if(typeof value==="number"){input=`<input data-path="${esc(path)}" type="number" step="any" value="${esc(value)}">`;}else if(typeof value==="boolean"){input=`<select data-path="${esc(path)}"><option value="true" ${value?"selected":""}>是</option><option value="false" ${!value?"selected":""}>否</option></select>`;}else{input=`<input data-path="${esc(path)}" type="text" value="${esc(value)}">`;}return `<label class="field">${esc(label)}${input}</label>`;}
function fieldGroup(prefix,keys,allowed={}){return `<div class="field-grid">${keys.filter((key)=>Object.hasOwn(getPath(state.config,prefix)||{},key)).map((key)=>field(`${prefix}.${key}`,getPath(state.config,`${prefix}.${key}`),allowed[key])).join("")}</div>`;}
function renderConfigForm(){const c=state.config;if(!c)return;$("config-name").value=c.name||"";options($("config-algorithm"),cat("algorithms"),(x)=>x.label||x.name||labels[x.id]||x.id,(x)=>x.id||x.name,"选择算法");if(!cat("algorithms").length){for(const key of ["sac","ppo","dqn"])$("config-algorithm").add(new Option(labels[key],key));}$("config-algorithm").value=c.algorithm;for(const button of document.querySelectorAll("[data-config-tab]"))button.setAttribute("aria-selected",button.dataset.configTab===state.configTab?"true":"false");let html="";
if(state.configTab==="state"){
  html=`<h3>状态特征 · 按选择顺序拼接</h3><div class="choice-list">${cat("features").map((f)=>{const key=f.id||f.name;const selected=c.state.features.includes(key);return `<label class="choice-card"><input type="checkbox" data-feature="${esc(key)}" ${selected?"checked":""} ${f.available===false||f.implemented===false?"disabled":""}><span><strong>${esc(f.label||labels[key]||key)}</strong><small>${esc(f.description||"")}</small>${f.available===false||f.implemented===false?"<em>待实现</em>":""}</span></label>`;}).join("")}</div><h3>已选特征的拼接顺序</h3><div class="choice-list">${c.state.features.map((key,i)=>`<div class="choice-card"><span><strong>${i+1}. ${esc(itemLabel("features",key))}</strong><small>${esc(key)}</small></span><span class="order-controls"><button type="button" data-move-feature="${esc(key)}" data-direction="-1" ${i===0?"disabled":""} aria-label="上移${esc(itemLabel("features",key))}">↑</button><button type="button" data-move-feature="${esc(key)}" data-direction="1" ${i===c.state.features.length-1?"disabled":""} aria-label="下移${esc(itemLabel("features",key))}">↓</button></span></div>`).join("")}</div><p class="small muted">顺序即模型输入顺序；选择变化会使旧权重不兼容。</p><h3>业务需求可见性</h3>${field("state.demand_visibility",c.state.demand_visibility,["known","online"])}<p class="field-note">已知模式允许使用当前场景的完整需求信息。逐步到达模式只能使用到当前步已知的需求。</p><h3>环境与动作规则</h3>${fieldGroup("environment",Object.keys(c.environment),{action_mode:["legacy_clip","feasible_projection"]})}`;
}else if(state.configTab==="network"){
  const networks=cat("networks");html=`<h3>网络模板</h3><div class="choice-list">${(networks.length?networks:[{id:"mlp"},{id:"cnn"},{id:"transformer"}]).map((n)=>{const key=n.id||n.kind||n.name;return `<label class="choice-card"><input type="radio" name="network-kind" data-network="${esc(key)}" ${c.network.kind===key?"checked":""} ${n.available===false?"disabled":""}><span><strong>${esc(n.label||labels[key]||key)}</strong><small>${esc(n.description||"")}</small></span></label>`;}).join("")}</div><h3>可编辑层参数</h3>${fieldGroup("network",["hidden_sizes","activation","dropout",...(c.network.kind==="cnn"?["cnn_channels","kernel_size"]:[]),...(c.network.kind==="transformer"?["embedding_dim","num_heads","num_layers","feedforward_dim"]:[])],{activation:["relu","gelu","tanh"]})}<p class="small muted">右侧结构和参数量由实际后台模型构建结果生成。</p>`;
}else if(state.configTab==="reward"){
  const terms=cat("reward_terms");html=`<h3>奖励预设</h3>${field("reward.preset",c.reward.preset,cat("presets").map((x)=>x.id||x.name))}<p class="small muted">原始、修正、融合预设的物理记账差别由后台校验；自定义项的结算时点和尺度会纳入配置。</p><h3>奖励分项</h3><div class="term-list">${terms.map((t)=>{const key=t.id||t.name;const selected=c.reward.terms.find((x)=>x.id===key);return `<div class="term-row"><label><input type="checkbox" data-term="${esc(key)}" ${selected?"checked":""} ${t.available===false||t.implemented===false?"disabled":""}> ${esc(t.label||key)}<small>${esc(t.description||"")}${t.timing?" · "+esc(t.timing):""}</small></label><label><span class="mini-label">权重</span><input type="number" step="any" data-term-weight="${esc(key)}" value="${esc(selected?.weight??t.default_weight??1)}" ${selected?"":"disabled"}></label><label><span class="mini-label">尺度</span><input type="number" step="any" data-term-scale="${esc(key)}" value="${esc(selected?.scale??t.default_scale??1)}" ${selected?"":"disabled"}></label></div>`;}).join("")}</div><h3>物理约束</h3>${fieldGroup("environment",Object.keys(c.environment),{action_mode:["legacy_clip","feasible_projection"]})}`;
}else{
  const common=["seed","total_steps","batch_size","gamma","gradient_clip","checkpoint_interval","log_interval","device"];
  const dedicated=c.algorithm==="sac"?["actor_lr","critic_lr","alpha_lr","tau","replay_capacity","warmup_steps","update_every","gradient_steps","initial_alpha","target_entropy"]:c.algorithm==="ppo"?["actor_lr","critic_lr","rollout_steps","ppo_epochs","gae_lambda","clip_ratio","entropy_coef","value_coef"]:["critic_lr","replay_capacity","warmup_steps","eps_start","eps_end","eps_decay_steps","target_update_interval"];
  const other=Object.keys(c.training).filter((k)=>![...common,...dedicated].includes(k));html=`<h3>通用训练设置</h3>${fieldGroup("training",common,{device:["cuda"]})}<h3>${esc(labels[c.algorithm]||c.algorithm)} 专属参数</h3>${fieldGroup("training",dedicated)}${other.length?`<details><summary>其余已定义参数</summary>${fieldGroup("training",other)}</details>`:""}<h3>实际训练场景</h3><label class="field">已保存场景集<select data-training-scene><option value="">按训练种子生成并保存场景</option>${state.scenes.map((s)=>`<option value="${esc(s.id)}" ${state.trainingSceneId===String(s.id)?"selected":""}>${esc(s.name||s.id)} · ${esc(s.count??"?")} 个场景</option>`).join("")}</select></label><p class="small muted">选择固定场景集时，任务会保存其实际路径；不选时按种子生成并归档训练场景。</p><h3>验证与考核</h3>${fieldGroup("evaluation",Object.keys(c.evaluation),{action_mode:["deterministic","stochastic"]})}<p class="field-note">最终考核场景不参与最佳模型选择。启动前服务器会核对 DQN 环境与 CUDA。</p>`;
}
$("config-form").innerHTML=html;}
function onConfigInput(target){if(!state.config)return;if(target.hasAttribute("data-training-scene")){state.trainingSceneId=target.value;localStorage.setItem("satellite-workbench-training-scene",target.value);return;}const path=target.dataset.path;if(path){let value=target.value;const old=getPath(state.config,path);if(target.dataset.array){value=value.split(/[，,\s]+/).filter(Boolean).map(Number);}else if(typeof old==="number"){value=value===""?null:Number(value);}else if(typeof old==="boolean"){value=value==="true";}setPath(state.config,path,value);}
else if(target.dataset.feature){const key=target.dataset.feature;let f=state.config.state.features;state.config.state.features=target.checked?[...f,key]:f.filter((x)=>x!==key);renderConfigForm();}
else if(target.dataset.network){state.config.network.kind=target.dataset.network;renderConfigForm();}
else if(target.dataset.term){const key=target.dataset.term;let t=state.config.reward.terms;state.config.reward.preset="custom";state.config.reward.terms=target.checked?[...t,{id:key,weight:Number(document.querySelector(`[data-term-weight="${CSS.escape(key)}"]`)?.value||1),scale:Number(document.querySelector(`[data-term-scale="${CSS.escape(key)}"]`)?.value||1),timing:lookup("reward_terms",key)?.timing||"step"}]:t.filter((x)=>x.id!==key);renderConfigForm();}
else if(target.dataset.termWeight||target.dataset.termScale){const key=target.dataset.termWeight||target.dataset.termScale;const term=state.config.reward.terms.find((x)=>x.id===key);if(term){term[target.dataset.termWeight?"weight":"scale"]=Number(target.value);state.config.reward.preset="custom";}}
saveDraft();scheduleValidation();}
function moveFeature(key,direction){const list=state.config.state.features,from=list.indexOf(key),to=from+direction;if(from<0||to<0||to>=list.length)return;[list[from],list[to]]=[list[to],list[from]];renderConfigForm();saveDraft();scheduleValidation();}
function saveDraft(){try{localStorage.setItem("satellite-workbench-draft-v1",JSON.stringify(state.config));}catch{}}
function loadDraft(){try{const raw=localStorage.getItem("satellite-workbench-draft-v1");return raw?JSON.parse(raw):null;}catch{return null;}}
function scheduleValidation(){state.validationSeq++;state.validated=null;$("config-state").textContent="有未检查更改";clearTimeout(state.validationTimer);state.validationTimer=setTimeout(()=>validate(false),500);}
async function validate(showToast=true){if(!state.config)return false;const seq=++state.validationSeq,raw=clone(state.config);try{const data=await api("/api/validate","POST",raw);if(seq!==state.validationSeq)return false;state.validated=data;state.config=data.config||state.config;saveDraft();renderSummary(data.summary||{},data.model||{});$("config-state").textContent="校验通过";$("config-state").classList.remove("bad");$("config-errors").textContent="配置与模型构建检查通过。";$("config-errors").className="notice good";$("config-warnings").innerHTML=(data.summary?.warnings||[]).map((x)=>`<p class="field-note warn">${esc(x)}</p>`).join("");if(showToast)notify("配置校验通过");return true;}catch(error){if(seq!==state.validationSeq)return false;state.validated=null;$("config-state").textContent="校验失败";$("config-state").classList.add("bad");$("config-errors").textContent=error.message;$("config-errors").className="notice bad";if(showToast)notify(error.message,true);return false;}}
function graphNode(node){const name={frequency:"频率槽起点",slots:"连续槽数",power:"功率档位"}[node.id]||node.label||node.name||node.type||node.id;return `<div class="network-node"><b>${esc(name)}</b><small>${esc(node.shape?`形状 ${JSON.stringify(node.shape)}`:"")}</small></div>`;}
function renderSummary(summary,model){$("state-dim").textContent=summary.state_dim??"—";$("state-visibility").textContent=labels[state.config.state?.demand_visibility]||state.config.state?.demand_visibility||"—";$("state-layout").innerHTML=(summary.state_layout||[]).map((r)=>`<li><strong>${esc(itemLabel("features",r.id))}</strong><span>${esc(r.offset??"?")}–${esc((r.offset??0)+(r.dim??0)-1)} · ${esc(r.dim??"?")} 维${r.shape?" · "+esc(JSON.stringify(r.shape)):""}</span></li>`).join("")||"<li>后台未返回拼接顺序</li>";$("reward-formula").textContent=typeof summary.reward_formula==="string"?summary.reward_formula:JSON.stringify(summary.reward_formula??"—",null,2);const count=model.parameter_count??model.parameters??model.param_count;$("parameter-count").textContent=count===undefined?"参数量未返回":`${txt(count)} 参数`;const nodes=model.nodes||model.graph?.nodes||model.layers||[],edges=model.edges||model.graph?.edges||[];const byId=Object.fromEntries(nodes.map((n)=>[n.id,n]));let markup="";if(byId.state&&byId.encoder&&edges.some((e)=>e.from==="state"&&e.to==="encoder")){const outputs=edges.filter((e)=>e.from==="encoder"&&byId[e.to]).map((e)=>byId[e.to]);markup=graphNode(byId.state)+'<div class="network-arrow" aria-hidden="true">↓</div>'+graphNode(byId.encoder)+'<div class="network-arrow" aria-hidden="true">↓</div><div class="network-branches">'+outputs.map(graphNode).join("")+"</div>";}else if(nodes.length){markup=nodes.map(graphNode).join("")+`<div class="small muted">${edges.map((e)=>`${esc(e.from)} → ${esc(e.to)}`).join(" · ")}</div>`;}$("network-graph").classList.toggle("empty",!nodes.length);$("network-graph").innerHTML=markup||"后台未返回可绘制的结构节点。";}
async function refreshSystem(){try{const s=await api("/api/system");state.system=s;const ok=s.cuda===true||s.cuda?.available===true;$("system-dot").className="status-dot "+(ok?"good":"bad");$("system-label").textContent=`${s.device||s.gpu?.name||"设备待核对"} · ${ok?"CUDA 可用":"CUDA 不可用"}`;$("system-label").title=`Python: ${s.python||"—"}\n源码: ${s.source_root||"—"}\n归档: ${s.archive_root||"—"}`;}catch(error){$("system-dot").className="status-dot bad";$("system-label").textContent=error.message;}}
async function refreshRuns(){try{const data=await api("/api/runs");state.runs=data.runs||[];options($("monitor-run"),state.runs,(x)=>`${x.name||x.run_id} · ${labels[x.stage]||x.stage||"—"}`,(x)=>x.run_id,"选择运行");if(state.selectedRun&&state.runs.some((x)=>x.run_id===state.selectedRun))$("monitor-run").value=state.selectedRun;options($("evaluation-run"),state.runs.filter((x)=>x.kind==="evaluate"||x.kind==="evaluation"),(x)=>`${x.name||x.run_id} · ${labels[x.stage]||x.stage||"—"}`,(x)=>x.run_id,"选择评价运行");const picked=new Set([...document.querySelectorAll(".monitor-overlay-choice:checked")].map((x)=>x.value));$("monitor-overlay").innerHTML=state.runs.filter((x)=>x.run_id!==$("monitor-run").value).map((r)=>`<label><input type="checkbox" class="monitor-overlay-choice" value="${esc(r.run_id)}" ${picked.has(r.run_id)?"checked":""}> ${esc(r.name||r.run_id)} <span class="small muted">${esc(labels[r.stage]||r.stage||"")}</span></label>`).join("")||'<span class="small muted">没有其他运行。</span>';renderCompareChoices();}catch(error){notify(error.message,true);}}
function renderCompareChoices(){const old=new Set([...document.querySelectorAll(".compare-choice:checked")].map((x)=>x.value));$("compare-choices").innerHTML=state.runs.map((run)=>`<label><input type="checkbox" class="compare-choice" value="${esc(run.run_id)}" ${old.has(run.run_id)?"checked":""}> <strong>${esc(run.name||run.run_id)}</strong><br><span class="small muted">${esc(labels[run.stage]||run.stage||"—")} · ${esc(labels[run.algorithm]||run.algorithm||"—")} · ${esc(run.kind||"训练")}</span></label>`).join("")||"<div class=\"notice muted\">暂无运行。</div>";}
async function refreshMonitor(){if(state.page!=="monitor")return;await Promise.allSettled([refreshRuns(),refreshSystem()]);const runId=$("monitor-run").value||state.selectedRun;if(!runId){$("monitor-banner").textContent="请选择运行；当前共 "+state.runs.length+" 条记录。";return;}state.selectedRun=runId;try{const [detail,metrics,logs]=await Promise.all([api(`/api/runs/${encodeURIComponent(runId)}`),api(`/api/runs/${encodeURIComponent(runId)}/metrics?limit=2000`),api(`/api/runs/${encodeURIComponent(runId)}/logs?limit=200`)]);const overlayIds=[...document.querySelectorAll(".monitor-overlay-choice:checked")].map((x)=>x.value);const overlays=await Promise.allSettled(overlayIds.map((x)=>api(`/api/runs/${encodeURIComponent(x)}/metrics?limit=2000`)));const combined={...metrics,series:[...(metrics.series||[])]};overlays.forEach((o,i)=>{if(o.status==="fulfilled"){const name=state.runs.find((x)=>x.run_id===overlayIds[i])?.name||overlayIds[i];combined.series.push(...(o.value.series||[]).map((s)=>({...s,tag:`${s.tag} · ${name}`,source_tag:s.tag})));}else{combined.diagnostics=[...(Array.isArray(combined.diagnostics)?combined.diagnostics:[]),{level:"warn",message:`对照运行 ${overlayIds[i]} 指标读取失败：${o.reason.message}`}];}});state.metrics=combined;state.logs=logs;renderMonitor(detail,combined,logs);renderArtifactChoices(detail,combined);const gpu=state.system?.gpu;if(gpu&&typeof gpu==="object")$("monitor-meta").insertAdjacentHTML("beforeend",`<div><span>全机 GPU 利用率</span>${esc(txt(gpu.utilization_percent,"%"))}</div><div><span>全机显存</span>${esc(txt(gpu.memory_used_mb," MB"))} / ${esc(txt(gpu.memory_total_mb," MB"))}</div>`);}catch(error){$("monitor-banner").textContent=error.message;$("monitor-banner").className="notice bad";}}
function metricTile(label,value,sub=""){return `<div class="metric-tile"><small>${esc(label)}</small><strong>${esc(value)}</strong>${sub?`<em>${esc(sub)}</em>`:""}</div>`;}
function renderMonitor(data,metrics,logs){const job=data.job||{},s=data.status||{},list=state.runs.find((x)=>x.run_id===state.selectedRun)||{};const stage=s.stage||list.stage||"unknown";const step=s.env_step??list.env_step;const budget=s.budget_env_steps??list.budget_env_steps;const progress=Number.isFinite(Number(step))&&Number.isFinite(Number(budget))&&Number(budget)>0?Math.min(100,100*step/budget):null;$("monitor-banner").textContent=`${labels[stage]||stage}${progress!==null?` · ${progress.toFixed(1)}%`:""}${list.read_only?" · 历史记录（只读）":""}`;$("monitor-banner").className="notice "+(stage==="failed"?"bad":stage==="completed"?"good":"muted");$("monitor-summary").innerHTML=[metricTile("交互步数",`${txt(step)} / ${txt(budget)}`,progress===null?"":`${progress.toFixed(1)}%`),metricTile("参数更新",txt(s.update_step)),metricTile("训练回合",txt(s.episode)),metricTile("交互吞吐",txt(s.steps_per_second," 步/秒")),metricTile("预计剩余",duration(s.eta_seconds)),metricTile("最新心跳",fmtTime(s.heartbeat_at))].join("");$("monitor-stop").disabled=!!list.read_only||!["queued","starting","initializing","warmup","training","validating","running","evaluating"].includes(stage);$("monitor-resume").disabled=!!list.read_only||!(["stopped","failed","interrupted"].includes(stage)&&!!(s.latest_checkpoint||data.artifacts?.checkpoint||data.artifacts?.latest_policy));$("monitor-download").disabled=false;$("monitor-source").textContent=`${escPlain(job.source_root||data.path||job.path||list.path||list.source||"来源待记录")} · ${job.git_commit||"提交号未返回"}`;$("monitor-meta").innerHTML=[["运行编号",state.selectedRun],["算法",labels[list.algorithm]||list.algorithm],["网络",labels[list.network]||list.network],["GPU",s.gpu||s.device],["显存",s.gpu_memory_mb?`${txt(s.gpu_memory_mb)} MB`:null],["已用时间",duration(s.wall_seconds)],["更新吞吐",s.updates_per_second!==undefined?`${txt(s.updates_per_second)} 次/秒`:null],["最后断点",s.latest_checkpoint||data.artifacts?.checkpoint],["创建时间",fmtTime(s.created_at||list.created_at)]].map(([a,b])=>`<div><span>${esc(a)}</span>${esc(b??"—")}</div>`).join("");$("monitor-raw-status").textContent=JSON.stringify({job,status:s,artifacts:data.artifacts,events:data.events},null,2);renderCharts(metrics);renderTagBrowser(metrics);renderLogs(logs);renderDiagnostics(s,metrics,logs);}
function escPlain(x){return String(x??"");}
function normalizedSeries(metrics){return (metrics?.series||[]).filter((s)=>Array.isArray(s.points)).map((s)=>({...s,tag:s.tag||s.name||"未命名指标",group:s.group||String(s.tag||"").split("/")[0]}));}
function matchesGroup(series,group){const tag=String(series.source_tag||series.tag).toLowerCase(),g=String(series.group).toLowerCase();return group.words.some((word)=>tag.includes(word)||g===word.replace("/",""));}
function renderCharts(metrics){const series=normalizedSeries(metrics),groups=scalarGroups.map((g)=>({title:g.title,items:[]})),other={title:"其他标量",items:[]};for(const item of series){const group=scalarGroups.findIndex((g)=>matchesGroup(item,g));(group<0?other:groups[group]).items.push(item);}if(other.items.length)groups.push(other);const plans=[],previous=[...document.querySelectorAll(".metric-group details")],openGroups=new Set(previous.filter((x)=>x.open).map((x)=>x.dataset.group));$("monitor-charts").innerHTML=groups.map((group,g)=>{const byTag=new Map();for(const item of group.items){const key=item.source_tag||item.tag;if(!byTag.has(key))byTag.set(key,[]);byTag.get(key).push(item);}const entries=[...byTag];entries.forEach(([tag,rows],i)=>plans.push({id:`metric-chart-${g}-${i}`,rows}));return `<div class="panel metric-group"><details data-group="${esc(group.title)}" ${previous.length?openGroups.has(group.title)?"open":"":g<2?"open":""}><summary><strong>${esc(group.title)}</strong><span>${entries.length} 项</span></summary>${entries.length?`<div class="metric-mini-grid">${entries.map(([tag],i)=>`<div class="metric-plot"><h3>${esc(tag)}</h3><div id="metric-chart-${g}-${i}" class="chart-box"></div></div>`).join("")}</div>`:'<div class="empty-state">没有该类真实标量</div>'}</details></div>`;}).join("");for(const plan of plans)drawChart($(plan.id),plan.rows);}
function renderTagBrowser(metrics){const all=normalizedSeries(metrics);const query=$("tag-search").value.trim().toLowerCase();const filtered=all.filter((s)=>!query||`${s.group} ${s.tag}`.toLowerCase().includes(query));const selected=$("tag-select").value;options($("tag-select"),filtered,(s)=>`${s.tag} (${s.points.length})`,(s)=>s.tag,"选择一个标量");if(filtered.some((s)=>s.tag===selected))$("tag-select").value=selected;else if(filtered.length)$("tag-select").value=filtered[0].tag;$("tag-count").textContent=`${all.length} 项标量`;const series=filtered.find((s)=>s.tag===$("tag-select").value);drawChart($("tag-chart"),series?[series]:[]);$("tag-table").innerHTML=`<table class="data-table"><thead><tr><th>标签</th><th>分组</th><th>点数</th><th>原始点数</th><th>最后步数</th><th>最后数值</th><th>记录时间</th></tr></thead><tbody>${filtered.map((s)=>{const p=s.points.at(-1)||{};return `<tr><td>${esc(s.tag)}</td><td>${esc(s.group)}</td><td>${s.points.length}${s.downsampled?"（已保留极值抽稀）":""}</td><td>${esc(s.raw_count??s.points.length)}</td><td>${esc(txt(p.step))}</td><td>${esc(txt(p.value))}</td><td>${esc(metricTimeLabel(p.wall_time))}</td></tr>`;}).join("")}</tbody></table>${filtered.length?"":"<p class=\"muted small\">没有匹配的标量。未记录的指标不会生成曲线。</p>"}`;}
function smooth(points,windowSize){if(windowSize<=1)return points;let values=[],sum=0;return points.map((p,i)=>{sum+=p.y;values.push(p.y);if(values.length>windowSize)sum-=values.shift();return {...p,y:sum/values.length};});}
function metricSeconds(value){if(value===null||value===undefined||value==="")return NaN;const number=Number(value);if(Number.isFinite(number))return number>1e12?number/1000:number;const parsed=Date.parse(value);return Number.isFinite(parsed)?parsed/1000:NaN;}
function seriesOrigin(points){const absolute=points.map((p)=>metricSeconds(p.wall_time)).filter((x)=>x>1e9);return absolute.length?Math.min(...absolute):0;}
function elapsedTime(value,origin){const seconds=metricSeconds(value);return Number.isFinite(seconds)?seconds>1e9?seconds-origin:seconds:NaN;}
function metricTimeLabel(value){const seconds=metricSeconds(value);return !Number.isFinite(seconds)?"—":seconds>1e9?fmtTime(seconds):duration(seconds);}
function shortDuration(value){return value>=3600?`${(value/3600).toFixed(1)}时`:value>=60?`${(value/60).toFixed(1)}分`:`${Number(value.toFixed(1))}秒`;}
function drawChart(container,series){if(!container)return;const axis=$("chart-axis").value;const raw=$("chart-show-raw").checked,smoothOn=$("chart-show-smooth").checked,windowSize=Math.max(1,Math.min(200,Number($("chart-smooth").value)||1));const lines=series.map((s)=>{const origin=seriesOrigin(s.points);return {tag:s.tag,points:s.points.map((p)=>({x:axis==="time"?elapsedTime(p.wall_time,origin):Number(p.step),y:Number(p.value),step:p.step,time:p.wall_time})).filter((p)=>Number.isFinite(p.x)&&Number.isFinite(p.y)).sort((a,b)=>a.x-b.x)};}).filter((s)=>s.points.length);if(!lines.length){container.innerHTML=`<div class="empty-state">${axis==="time"?"这些标量没有实际记录时间；可切换交互步数查看。":"没有可绘制的真实记录"}</div>`;return;}const all=lines.flatMap((x)=>x.points),minX=Math.min(...all.map((x)=>x.x)),maxX=Math.max(...all.map((x)=>x.x)),minY=Math.min(...all.map((x)=>x.y)),maxY=Math.max(...all.map((x)=>x.y));const width=640,height=220,pad={left:57,right:16,top:16,bottom:36};const X=(x)=>pad.left+(x-minX)/(maxX-minX||1)*(width-pad.left-pad.right);const Y=(y)=>height-pad.bottom-(y-minY)/(maxY-minY||1)*(height-pad.top-pad.bottom);let paths="";lines.forEach((line,i)=>{const color=palette[i%palette.length];for(const [kind,points] of [["raw",line.points],["smooth",smooth(line.points,windowSize)]]){if((kind==="raw"&&!raw)||(kind==="smooth"&&!smoothOn))continue;const d=points.map((p,j)=>`${j?"L":"M"}${X(p.x).toFixed(1)} ${Y(p.y).toFixed(1)}`).join(" ");paths+=`<path class="line ${kind}" d="${d}" stroke="${color}"><title>${esc(line.tag)} · ${kind==="raw"?"原始":"平滑"}</title></path>`;}});const yticks=[0,.25,.5,.75,1].map((f)=>{const value=minY+(maxY-minY)*f,y=Y(value);return `<line class="grid" x1="${pad.left}" x2="${width-pad.right}" y1="${y}" y2="${y}"/><text x="${pad.left-5}" y="${y+3}" text-anchor="end">${esc(shortNumber(value))}</text>`;}).join("");const xticks=[0,.25,.5,.75,1].map((f)=>{const value=minX+(maxX-minX)*f,x=X(value);return `<text x="${x}" y="${height-11}" text-anchor="middle">${esc(axis==="time"?shortDuration(value):shortNumber(value))}</text>`;}).join("");container.innerHTML=`<div class="chart-legend">${lines.map((s,i)=>`<span><i style="background:${palette[i%palette.length]}"></i>${esc(s.tag)}</span>`).join("")}</div><svg class="chart-svg" role="img" aria-label="${esc(lines.map((s)=>s.tag).join("、"))}实际记录曲线" viewBox="0 0 ${width} ${height}" preserveAspectRatio="none">${yticks}<line class="axis" x1="${pad.left}" y1="${height-pad.bottom}" x2="${width-pad.right}" y2="${height-pad.bottom}"/>${paths}${xticks}<rect class="plot-hit" x="${pad.left}" y="${pad.top}" width="${width-pad.left-pad.right}" height="${height-pad.top-pad.bottom}"/></svg>`;const svg=container.querySelector("svg");svg.addEventListener("pointermove",(event)=>{const rect=svg.getBoundingClientRect(),px=(event.clientX-rect.left)/rect.width*width,targetX=minX+(Math.max(pad.left,Math.min(width-pad.right,px))-pad.left)/(width-pad.left-pad.right)*(maxX-minX);const nearest=lines.map((line)=>line.points.reduce((best,p)=>Math.abs(p.x-targetX)<Math.abs(best.x-targetX)?p:best,line.points[0])).map((p,i)=>({p,tag:lines[i].tag})).sort((a,b)=>Math.abs(a.p.x-targetX)-Math.abs(b.p.x-targetX))[0];let tip=container.querySelector(".chart-tooltip");if(!tip){tip=document.createElement("div");tip.className="chart-tooltip";container.append(tip);}tip.textContent=`${nearest.tag} · ${txt(nearest.p.y)} · ${axis==="time"?duration(nearest.p.x):`第 ${txt(nearest.p.step)} 步`}`;tip.style.left=Math.min(rect.width-200,Math.max(0,event.clientX-rect.left+8))+"px";tip.style.top=Math.max(0,event.clientY-rect.top-28)+"px";});svg.addEventListener("pointerleave",()=>container.querySelector(".chart-tooltip")?.remove());}
function shortNumber(n){return Math.abs(n)>=1e6?(n/1e6).toFixed(1)+"M":Math.abs(n)>=1e3?(n/1e3).toFixed(1)+"k":Number(n.toPrecision(3)).toString();}
function renderLogs(logs){const lines=logs.lines||[];$("monitor-logs").textContent=lines.length?lines.map((x)=>typeof x==="string"?x:JSON.stringify(x)).join("\n"):"暂无日志。";$("monitor-events").innerHTML=(logs.events||[]).slice(-60).reverse().map((event)=>`<div class="event"><small>${esc(fmtTime(event.at||event.time))}</small> <b>${esc(event.kind||event.type||"事件")}</b><div>${esc(event.message||event.reason||event.error||"")}</div></div>`).join("")||'<p class="muted small">暂无事件。</p>';}
function renderArtifactChoices(detail,metrics){const names=Object.keys(detail.artifacts||{}).filter((name)=>/^(metrics|updates|episodes|evaluations|traces|events|worker|status|config|job|manifest|results|failure|artifacts)\.(jsonl|csv|json|log)$/.test(name));options($("monitor-file"),names,(x)=>x,(x)=>x,"选择原始文件");if(names.length&&!$("monitor-file").value)$("monitor-file").value=names.includes("updates.csv")?"updates.csv":names.includes("metrics.jsonl")?"metrics.jsonl":names[0];$("monitor-download").disabled=!names.length;const source=(metrics.sources||[]).join("、");if(source)$("monitor-meta").insertAdjacentHTML("beforeend",`<div><span>指标来源</span>${esc(source)}</div>`);const preflight=detail.status?.preflight;if(preflight)$("monitor-meta").insertAdjacentHTML("beforeend",`<div><span>启动检查</span>${esc(typeof preflight==="string"?preflight:JSON.stringify(preflight))}</div>`);}
function renderDiagnostics(status,metrics,logs){const hints=[];const now=Date.now(),hb=new Date(status.heartbeat_at).getTime(),stage=status.stage||"";if(stage==="failed")hints.push({level:"bad",text:`任务失败。请查看错误日志和最后正常断点：${status.latest_checkpoint||"未记录"}。`});if(["training","warmup","validating","evaluating","running"].includes(stage)&&Number.isFinite(hb)&&now-hb>60000)hints.push({level:"warn",text:`最近心跳距今 ${duration((now-hb)/1000)}。请核对实际进程与日志；状态可能滞后。`});if(status.steps_per_second===0&&["training","warmup"].includes(stage))hints.push({level:"warn",text:"状态记录的交互吞吐为 0 步/秒；请结合最近心跳和日志判断是否正在等待。"});if(!normalizedSeries(metrics).length)hints.push({level:"",text:"尚无可用标量曲线。训练可能尚未达到日志间隔，或原运行没有记录此类指标。"});const ds=metrics.diagnostics;if(Array.isArray(ds))for(const d of ds)hints.push({level:d.level||"",text:d.message||String(d),details:d.details});else if(ds&&typeof ds==="object")for(const [key,val] of Object.entries(ds))hints.push({level:"",text:`${key}: ${typeof val==="string"?val:JSON.stringify(val)}`});$("monitor-diagnostics").innerHTML=hints.map((x)=>`<div class="diagnostic ${esc(x.level)}">${esc(x.text)}${x.details?`<details><summary>查看原始详情</summary><pre class="diagnostic-detail">${esc(typeof x.details==="string"?x.details:JSON.stringify(x.details,null,2))}</pre></details>`:""}</div>`).join("")||'<p class="muted small">未检测到可由当前记录确认的异常。</p>';}
async function refreshResources(){try{const [m,s]=await Promise.all([api("/api/models"),api("/api/scenes")]);state.models=m.models||[];state.scenes=s.scenes||[];options($("model-select"),state.models,(x)=>`${x.name||x.id} · ${x.format||labels[x.algorithm]||x.algorithm||""}`,(x)=>x.id,"选择模型");options($("scene-select"),state.scenes,(x)=>`${x.name||x.id} · ${x.count??"?"} 个场景`,(x)=>x.id,"选择场景集");renderSelectionDetails();await refreshRuns();}catch(error){notify(error.message,true);}}
function renderSelectionDetails(){const model=state.models.find((x)=>String(x.id)===$("model-select").value),scene=state.scenes.find((x)=>String(x.id)===$("scene-select").value);$("model-details").textContent=model?`格式：${model.format||"—"} · 算法：${labels[model.algorithm]||model.algorithm||"—"} · ${model.compatible===false?"已标记不兼容":model.compatible===true?"已标记兼容":"兼容性将在评价时检查"}\n${model.path||""}`:"尚未选择模型。";$("model-details").className="notice "+(model?.compatible===false?"bad":"muted");$("scene-details").textContent=scene?`场景集：${scene.name||scene.id} · 场景数量：${scene.count??"—"}，每个场景 100 束\n${scene.path||""}`:"尚未选择场景。";}
async function importModel(){const path=$("model-path").value.trim();if(!path){notify("请输入本地权重路径",true);return;}let config;try{const raw=$("model-config-json").value.trim();if(raw)config=JSON.parse(raw);}catch(error){notify("模型配置 JSON 无效："+error.message,true);return;}try{const model=await api("/api/models/import","POST",{path,config,legacy_type:$("model-legacy-type").value||undefined});notify("模型已导入并检查");await refreshResources();if(model.id)$("model-select").value=model.id;renderSelectionDetails();}catch(error){notify(error.message,true);}}
async function createScene(importExisting){try{let body,path=importExisting?"/api/scenes/import":"/api/scenes";if(importExisting){const source=$("scene-path").value.trim();if(!source)throw new Error("请输入本地场景路径");body={path:source,name:$("scene-name").value.trim()||undefined};}else{body={name:$("scene-name").value.trim()||"新测试场景",seed:Number($("scene-seed").value),count:Number($("scene-count").value)};}const scene=await api(path,"POST",body);notify("实际场景已保存");await refreshResources();if(scene.id)$("scene-select").value=scene.id;renderSelectionDetails();}catch(error){notify(error.message,true);}}
async function startEvaluation(){const model_id=$("model-select").value,scene_id=$("scene-select").value;if(!model_id||!scene_id){notify("请选择模型和实际场景",true);return;}const model=state.models.find((x)=>String(x.id)===model_id);if(model?.compatible===false){notify("该模型已标记不兼容，无法评价",true);return;}try{const data=await api("/api/evaluations","POST",{model_id,scene_id,action_mode:$("test-action-mode").value,repeats:Number($("test-repeats").value),request_id:id(),baselines:[...document.querySelectorAll(".baseline-choice:checked")].map((x)=>x.value)});notify(`评价任务已提交：${data.run_id}`);await refreshRuns();$("evaluation-run").value=data.run_id;$("evaluation-state").textContent=`任务 ${data.run_id} 已提交，等待结果。`;$("test-results").hidden=true;}catch(error){notify(error.message,true);}}
async function loadEvaluation(){const runId=$("evaluation-run").value;if(!runId){notify("请选择评价运行",true);return;}try{const data=await api(`/api/runs/${encodeURIComponent(runId)}/results`);if(!data||(!data.summary&&!data.scenes?.length)){$("evaluation-state").textContent="评价尚未生成结果；请等待后台完成后刷新。";$("test-results").hidden=true;return;}state.results=data;renderResults(data);renderBaselineNotes(data);$("evaluation-state").textContent=`已读取 ${data.scenes?.length||0} 个实际场景的结果。`;}catch(error){$("evaluation-state").textContent=error.message;$("evaluation-state").className="notice bad";$("test-results").hidden=true;}}
function renderBaselineNotes(data){const notes=normalizeBaselines(data.baselines).map((b)=>`${b.name}：${b.metadata?.note||"同场景评价"}${b.metadata?.exact_power_match===false?"；功率档位经过映射，不能称为完全相同的动作档位":""}`);if(notes.length)$("baseline-results").insertAdjacentHTML("beforeend",notes.map((x)=>`<p class="small muted">${esc(x)}</p>`).join(""));}
function normalizeBaselines(value){return Array.isArray(value)?value:Object.entries(value||{}).map(([name,body])=>({name,...body}));}
function renderResults(data){$("test-results").hidden=false;const sum=data.summary||{};const keys=["final_si_mean","final_sgm_mean","basic_met_count","throughput_bps","power_w","radiated_power_w","zero_capacity_count","overload","complete","clipped_count","actual_slots","jain"];$("test-summary").innerHTML=keys.filter((k)=>sum[k]!==undefined).map((k)=>metricTile(labels[k]||k,typeof sum[k]==="boolean"?(sum[k]?"是":"否"):txt(sum[k]))).join("")||metricTile("总体结果","指标缺失");const baselines=normalizeBaselines(data.baselines);$("baseline-results").innerHTML=baselines.length?`<h3>同场景基线成绩</h3><p class="small muted">各列来自同一实际场景集的终态统计。模型与基线的训练回报不作排名。</p><div class="table-wrap"><table class="data-table"><thead><tr><th>策略</th>${keys.map((k)=>`<th>${esc(labels[k]||k)}</th>`).join("")}</tr></thead><tbody>${[{name:"当前模型",summary:sum},...baselines].map((row)=>`<tr><td>${esc(row.name)}</td>${keys.map((k)=>`<td>${esc(row.summary?.[k]===undefined?"—":typeof row.summary[k]==="boolean"?row.summary[k]?"是":"否":txt(row.summary[k]))}</td>`).join("")}</tr>`).join("")}</tbody></table></div>`:'<p class="muted small">本次未返回同场景基线结果。</p>';options($("baseline-view"),baselines,(b)=>b.name,(b)=>b.name,"仅当前模型");const scenes=data.scenes||[];options($("result-scene"),scenes,(s)=>s.scene_id||s.id||s.name,(s)=>s.scene_id||s.id||s.name,"选择场景");if(scenes.length&&!$("result-scene").value)$("result-scene").value=scenes[0].scene_id||scenes[0].id||scenes[0].name;renderSceneResult();}
function renderSceneResult(){const scene=(state.results?.scenes||[]).find((s)=>String(s.scene_id||s.id||s.name)===$("result-scene").value);if(!scene)return;const beams=scene.beams||scene.beam_results||[];const baseline=normalizeBaselines(state.results?.baselines).find((b)=>b.name===$("baseline-view").value),baselineScene=baseline?.scenes?.find((s)=>(s.scene?.source_sha256&&s.scene.source_sha256===scene.scene?.source_sha256)||String(s.scene_id||s.id||s.name)===String(scene.scene_id||scene.id||scene.name)),baselineBeams=baselineScene?.beams||baselineScene?.beam_results||[];$("beam-table").innerHTML=beams.length?`<table class="data-table"><thead><tr><th>波束</th><th>组</th><th>需求 / bps</th><th>最终速率 / bps</th>${baselineBeams.length?`<th>${esc(baseline.name)}速率 / bps</th>`:""}<th>需求满足率</th><th>SGM</th><th>频率起点</th><th>槽数</th><th>功率 / W</th><th>基本服务</th></tr></thead><tbody>${beams.map((b,i)=>`<tr><td>${esc(b.beam_id??"—")}</td><td>${esc(b.group??"—")}</td><td>${esc(txt(b.required_bps))}</td><td>${esc(txt(b.rate_bps))}</td>${baselineBeams.length?`<td>${esc(txt(baselineBeams[i]?.rate_bps))}</td>`:""}<td>${esc(txt(b.si))}</td><td>${esc(txt(b.sgm))}</td><td>${esc(b.freq??"—")}</td><td>${esc(b.slots??"—")}</td><td>${esc(txt(b.power_w))}</td><td>${b.basic_met===undefined?"—":b.basic_met?"达标":"未达标"}</td></tr>`).join("")}</tbody></table>`:'<div class="empty-state">没有逐束结果记录</div>';if(baselineBeams.length)drawBaselineBars($("beam-chart"),beams,baselineBeams,baseline.name);else drawBarComparison($("beam-chart"),beams,"required_bps","rate_bps","需求","最终速率");drawBarComparison($("power-chart"),beams,"power_w",null,"实际功率",null);$("spectrum-chart").innerHTML=beams.some((x)=>x.freq!==undefined)?`<p class="small muted">每行对应一束；横轴为所在组的 100 个频率槽，色块是实际连续占用范围。</p>`+beams.map((b)=>{const start=Number(b.freq),count=Number(b.slots),valid=b.freq!==null&&Number.isFinite(start)&&Number.isFinite(count)&&start>=0&&start<100&&count>=0;const width=valid?Math.max(0,Math.min(100-start,count)):0;return `<div class="spectrum-row"><span>组${esc(b.group??"—")} · ${esc(b.beam_id??"—")}</span><div class="spectrum-track" title="组 ${esc(b.group??"—")}，频率槽起点 ${esc(b.freq??"—")}，实际槽数 ${esc(b.slots??"—")}"><i style="margin-left:${valid?start:0}%;width:${width}%"></i></div><small>${esc(b.freq??"—")}</small></div>`;}).join(""):'<div class="empty-state">没有频率槽记录</div>';const trace=scene.trace||scene.traces||[];$("trace-view").textContent=trace.length?trace.slice(0,300).map((t,i)=>`${i+1}. 请求 ${JSON.stringify(t.requested_action||t.requested||"—")} → 实际 ${JSON.stringify(t.actual_action||t.actual||"—")} · 奖励 ${txt(t.reward)}`).join("\n"):"没有逐步动作记录。";}
function drawBaselineBars(container,beams,baselineBeams,name){const rows=beams.map((b,i)=>({required:Number(b.required_bps),model:Number(b.rate_bps),baseline:Number(baselineBeams[i]?.rate_bps)}));const max=Math.max(1,...rows.flatMap((r)=>[r.required,r.model,r.baseline].filter(Number.isFinite)));const w=640,h=220,left=42,right=12,bottom=30,top=8,band=(w-left-right)/Math.max(1,rows.length);let rects="";rows.forEach((r,i)=>{[r.required,r.model,r.baseline].forEach((v,j)=>{if(!Number.isFinite(v))return;const height=v/max*(h-bottom-top),bw=Math.max(1,Math.min(5,band*.27));rects+=`<rect x="${left+i*band+j*bw}" y="${h-bottom-height}" width="${bw}" height="${height}" fill="${palette[j]}"><title>波束 ${i+1} · ${["需求","当前模型",name][j]} ${v}</title></rect>`;});});container.innerHTML=`<div class="chart-legend">${["业务需求","当前模型速率",name+"速率"].map((label,i)=>`<span><i style="background:${palette[i]}"></i>${esc(label)}</span>`).join("")}</div><svg role="img" aria-label="同场景逐束业务需求、模型和基线最终速率" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none"><line x1="${left}" x2="${w-right}" y1="${h-bottom}" y2="${h-bottom}" stroke="#a8bdc9"/><text x="${left-5}" y="${top+9}" text-anchor="end" fill="#7890a0" font-size="10">${esc(shortNumber(max))}</text>${rects}<text x="${w-right}" y="${h-6}" text-anchor="end" fill="#7890a0" font-size="10">波束序号 →</text></svg>`;}
function drawBarComparison(container,rows,key1,key2,label1,label2){const points=rows.map((x)=>({a:Number(x[key1]),b:key2?Number(x[key2]):null})).filter((x)=>Number.isFinite(x.a));if(!points.length){container.innerHTML='<div class="empty-state">没有可绘制的真实记录</div>';return;}const max=Math.max(1,...points.flatMap((x)=>[x.a,x.b??0]));const w=640,h=220,left=42,right=12,bottom=30,top=8,usable=w-left-right,band=usable/points.length;let rects="";points.forEach((p,i)=>{const x=left+i*band,barW=Math.max(1,Math.min(8,band*(key2?.32:.6)));const ah=(p.a/max)*(h-bottom-top),bh=(p.b??0)/max*(h-bottom-top);rects+=`<rect x="${x+band*.1}" y="${h-bottom-ah}" width="${barW}" height="${ah}" fill="${palette[0]}"><title>波束 ${i+1} · ${label1} ${p.a}</title></rect>`;if(key2)rects+=`<rect x="${x+band*.1+barW+1}" y="${h-bottom-bh}" width="${barW}" height="${bh}" fill="${palette[1]}"><title>波束 ${i+1} · ${label2} ${p.b}</title></rect>`;});container.innerHTML=`<div class="chart-legend"><span><i style="background:${palette[0]}"></i>${esc(label1)}</span>${key2?`<span><i style="background:${palette[1]}"></i>${esc(label2)}</span>`:""}</div><svg role="img" aria-label="${esc(label1)}${key2?`与${label2}`:""}逐束分布" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none"><line x1="${left}" x2="${w-right}" y1="${h-bottom}" y2="${h-bottom}" stroke="#a8bdc9"/><text x="${left-5}" y="${top+9}" text-anchor="end" fill="#7890a0" font-size="10">${esc(shortNumber(max))}</text>${rects}<text x="${w-right}" y="${h-6}" text-anchor="end" fill="#7890a0" font-size="10">波束序号 →</text></svg>`;}
async function compare(){const run_ids=[...document.querySelectorAll(".compare-choice:checked")].map((x)=>x.value);if(run_ids.length<2){notify("至少选择两个运行",true);return;}try{const data=await api("/api/compare","POST",{run_ids});state.comparison=data;renderComparison(data);renderConfigDifferences(data.runs||[]);notify("配对结果已生成");}catch(error){$("compare-notice").textContent=error.message;$("compare-notice").className="notice bad";$("compare-output").hidden=true;notify(error.message,true);}}
function renderComparison(data){$("compare-output").hidden=false;$("compare-notice").textContent=`已对比 ${data.runs?.length||0} 个运行；请查看配对口径与警告。`;$("compare-notice").className="notice good";$("compare-warnings").innerHTML=(data.warnings||[]).map((x)=>`<div class="notice warn">${esc(x)}</div>`).join("");const rows=data.rows||[];const cols=[...new Set(rows.flatMap((x)=>Object.keys(x)))];$("compare-table").innerHTML=rows.length?`<table class="data-table"><thead><tr>${cols.map((k)=>`<th>${esc(labels[k]||k)}</th>`).join("")}</tr></thead><tbody>${rows.map((r)=>`<tr>${cols.map((k)=>`<td>${esc(typeof r[k]==="object"?JSON.stringify(r[k]):r[k]??"—")}</td>`).join("")}</tr>`).join("")}</tbody></table>`:'<div class="empty-state">服务端没有返回配对行；请检查场景和口径警告。</div>';$("compare-configs").innerHTML=(data.runs||[]).map((r)=>`<div><strong>${esc(r.name||r.run_id||r.id||"运行")}</strong>\n${esc(JSON.stringify(r.config||r,null,2))}</div>`).join("");}
function flattenConfig(value,prefix="",out={}){if(value&&typeof value==="object"&&!Array.isArray(value)){for(const [key,item] of Object.entries(value))flattenConfig(item,prefix?`${prefix}.${key}`:key,out);}else out[prefix]=value;return out;}
function renderConfigDifferences(runs){const maps=runs.map((r)=>flattenConfig(r.config||{})),keys=[...new Set(maps.flatMap((m)=>Object.keys(m)))].filter((key)=>new Set(maps.map((m)=>JSON.stringify(m[key]))).size>1);$("compare-configs").innerHTML=`<div class="config-diff"><h3>配置差异</h3>${keys.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>配置项</th>${runs.map((r)=>`<th>${esc(r.name||r.run_id)}</th>`).join("")}</tr></thead><tbody>${keys.map((key)=>`<tr><td>${esc(key)}</td>${maps.map((m)=>`<td>${esc(JSON.stringify(m[key]??"—"))}</td>`).join("")}</tr>`).join("")}</tbody></table></div>`:'<p class="muted small">所选运行的配置字段相同。</p>'}</div>`;}
function downloadJson(filename,data){const blob=new Blob([JSON.stringify(data,null,2)],{type:"application/json"}),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function saveConfig(){if(!await validate(false)){notify("请先修正配置错误",true);return;}try{const result=await api("/api/configs","POST",{name:state.config.name,config:state.validated.config});notify(`方案已保存${result.id?`：${result.id}`:""}`);}catch(error){notify(error.message,true);}}
async function startTraining(){if(state.requestBusy)return;if(!await validate(false)){notify("配置未通过校验，无法提交",true);return;}state.requestBusy=true;$("config-start").disabled=true;try{const result=await api("/api/runs","POST",{config:state.validated.config,request_id:id(),...(state.trainingSceneId?{scene_id:state.trainingSceneId}:{})});state.selectedRun=result.run_id;notify(`训练任务已提交：${result.run_id}`);setPage("monitor");}catch(error){notify(error.message,true);}finally{state.requestBusy=false;$("config-start").disabled=false;}}
async function refreshSceneCatalog(){try{const data=await api("/api/scenes");state.scenes=data.scenes||[];if(state.configTab==="training")renderConfigForm();}catch(error){notify(error.message,true);}}
async function loadSavedConfigs(){try{const data=await api("/api/configs"),list=data.configs||[];options($("saved-config-select"),list,(x)=>x.name||x.id,(x)=>x.id,"选择方案");$("config-dialog").showModal();$("config-dialog")._items=list;}catch(error){notify(error.message,true);}}
function wire(){document.querySelectorAll("[data-page]").forEach((x)=>x.addEventListener("click",()=>setPage(x.dataset.page)));document.querySelectorAll("[data-config-tab]").forEach((x)=>x.addEventListener("click",()=>{state.configTab=x.dataset.configTab;renderConfigForm();}));$("config-name").addEventListener("input",(e)=>{state.config.name=e.target.value;saveDraft();});$("config-algorithm").addEventListener("change",(e)=>{state.config.algorithm=e.target.value;renderConfigForm();saveDraft();scheduleValidation();});$("config-form").addEventListener("change",(e)=>onConfigInput(e.target));$("config-form").addEventListener("input",(e)=>{if(e.target.matches("[data-path],[data-term-weight],[data-term-scale]"))onConfigInput(e.target);});$("config-validate").addEventListener("click",()=>validate());$("config-save").addEventListener("click",saveConfig);$("config-start").addEventListener("click",startTraining);$("config-export").addEventListener("click",()=>state.config&&downloadJson(`${(state.config.name||"实验配置").replace(/[\\/:*?"<>|]/g,"_")}.json`,state.config));$("config-import").addEventListener("click",()=>$("config-file").click());$("config-file").addEventListener("change",async(e)=>{try{const file=e.target.files?.[0];if(!file)return;state.config=JSON.parse(await file.text());renderConfigForm();saveDraft();await validate();}catch(error){notify("导入失败："+error.message,true);}finally{e.target.value="";}});$("config-load").addEventListener("click",loadSavedConfigs);$("saved-config-apply").addEventListener("click",()=>{const item=$("config-dialog")._items?.find((x)=>String(x.id)===$("saved-config-select").value);if(item){state.config=clone(item.config||item);renderConfigForm();saveDraft();scheduleValidation();}});$("system-refresh").addEventListener("click",refreshSystem);$("monitor-run").addEventListener("change",()=>{state.selectedRun=$("monitor-run").value;refreshMonitor();});$("monitor-refresh").addEventListener("click",refreshMonitor);for(const key of ["chart-axis","chart-smooth","chart-show-raw","chart-show-smooth"])$(key).addEventListener("change",()=>{renderCharts(state.metrics||{});renderTagBrowser(state.metrics||{});});$("tag-search").addEventListener("input",()=>renderTagBrowser(state.metrics||{}));$("tag-select").addEventListener("change",()=>renderTagBrowser(state.metrics||{}));$("monitor-stop").addEventListener("click",()=>runAction("stop"));$("monitor-resume").addEventListener("click",()=>runAction("resume"));$("monitor-download").addEventListener("click",()=>{const run=state.selectedRun;if(run)window.location.href=`/api/runs/${encodeURIComponent(run)}/download?file=metrics.jsonl`;});$("test-refresh").addEventListener("click",refreshResources);$("model-select").addEventListener("change",renderSelectionDetails);$("scene-select").addEventListener("change",renderSelectionDetails);$("model-import").addEventListener("click",importModel);$("scene-generate").addEventListener("click",()=>createScene(false));$("scene-import").addEventListener("click",()=>createScene(true));$("test-start").addEventListener("click",startEvaluation);$("evaluation-load").addEventListener("click",loadEvaluation);$("result-scene").addEventListener("change",renderSceneResult);$("compare-refresh").addEventListener("click",refreshRuns);$("compare-run").addEventListener("click",compare);$("compare-export").addEventListener("click",()=>state.comparison&&downloadJson("配对结果.json",state.comparison));window.addEventListener("hashchange",()=>{const name=location.hash.slice(1);if(["config","monitor","test","compare"].includes(name))setPage(name);});}
async function runAction(action){if(!state.selectedRun)return;try{await api(`/api/runs/${encodeURIComponent(state.selectedRun)}/${action}`,"POST",{});notify(action==="stop"?"已请求安全停止并保存":"已请求从断点恢复");refreshMonitor();}catch(error){notify(error.message,true);}}
async function init(){wire();$("config-form").addEventListener("click",(event)=>{const button=event.target.closest("[data-move-feature]");if(button)moveFeature(button.dataset.moveFeature,Number(button.dataset.direction));});document.querySelector('[data-config-tab="training"]').addEventListener("click",refreshSceneCatalog);$("monitor-overlay").addEventListener("change",refreshMonitor);$("monitor-download").addEventListener("click",(event)=>{event.stopImmediatePropagation();const run=state.selectedRun,file=$("monitor-file").value;if(run&&file)window.location.href=`/api/runs/${encodeURIComponent(run)}/download?file=${encodeURIComponent(file)}`;},true);$("model-download").addEventListener("click",()=>{const id=$("model-select").value;if(!id){notify("请先选择模型",true);return;}window.location.href=`/api/models/${encodeURIComponent(id)}/download`;});for(const [button,file] of [["test-report-download","report.md"],["test-csv-download","beam_results.csv"],["test-json-download","results.json"]])$(button).addEventListener("click",()=>{const run=$("evaluation-run").value;if(run)window.location.href=`/api/runs/${encodeURIComponent(run)}/download?file=${encodeURIComponent(file)}`;});$("baseline-view").addEventListener("change",renderSceneResult);try{const data=await api("/api/catalog");state.catalog=data;state.defaults=data.defaults||data.default_config;if(!state.defaults)throw new Error("服务未提供默认配置");state.config=loadDraft()||clone(state.defaults);renderConfigForm();await validate(false);}catch(error){$("config-errors").textContent=error.message;$("config-errors").className="notice bad";notify(error.message,true);}await Promise.allSettled([refreshSystem(),refreshRuns(),refreshSceneCatalog()]);const page=location.hash.slice(1);if(["config","monitor","test","compare"].includes(page))setPage(page);state.poll=setInterval(()=>{if(state.page==="monitor")refreshMonitor();else if(state.page==="test"&&$("evaluation-run").value)loadEvaluation();},7000);}
document.addEventListener("DOMContentLoaded",init);
